// Analyse workflows + executions and build one actionable finding per problem.
const cfg = $('Config').first().json;
const workflows = $('Get active workflows').first().json.data || [];
const executions = $('Get recent executions').first().json.data || [];
const now = Date.now();
const min = 60 * 1000;
const findings = [];
const byWf = {};
for (const e of executions) { (byWf[e.workflowId] = byWf[e.workflowId] || []).push(e); }
const name = (id) => (workflows.find(w => String(w.id) === String(id)) || {}).name || `Workflow ${id}`;
const link = (e) => `${cfg.baseUrl}/workflow/${e.workflowId}/executions/${e.id}`;

// 1) Failed executions inside the window
for (const e of executions) {
  const t = Date.parse(e.stoppedAt || e.startedAt);
  if ((e.status === 'error' || e.status === 'crashed') && now - t <= cfg.windowMinutes * min) {
    findings.push({ kind: 'failed', workflow: name(e.workflowId),
      what: `Execution ${e.id} ended with status "${e.status}".`,
      next: `Open the execution, fix the failing node, then re-run it to backfill.`, url: link(e) });
  }
}

// 2) Stuck executions (still running too long)
for (const e of executions) {
  if ((e.status === 'running' || (!e.finished && !e.stoppedAt)) && now - Date.parse(e.startedAt) > cfg.stuckMinutes * min) {
    findings.push({ kind: 'stuck', workflow: name(e.workflowId),
      what: `Execution ${e.id} has been running for ${Math.round((now - Date.parse(e.startedAt)) / min)} min (limit ${cfg.stuckMinutes}).`,
      next: `Check worker/main logs (OOM or restart?). Stop the execution and re-run if needed.`, url: link(e) });
  }
}

// 3) Silent schedules: expected interval from the Schedule Trigger rule
const unitMs = { seconds: 1000, minutes: min, hours: 60 * min, days: 1440 * min, weeks: 10080 * min, months: 43200 * min };
for (const w of workflows) {
  const trig = (w.nodes || []).find(n => n.type === 'n8n-nodes-base.scheduleTrigger' && !n.disabled);
  if (!trig) continue;
  const rules = (trig.parameters && trig.parameters.rule && trig.parameters.rule.interval) || [];
  let expected = null;
  for (const r of rules) {
    const field = r.field || 'days';
    const every = r[`${field}Interval`] || 1;
    const ms = (unitMs[field] || unitMs.days) * every;
    expected = expected === null ? ms : Math.min(expected, ms);
  }
  if (!expected) continue; // cron expressions etc. are skipped
  const runs = (byWf[w.id] || []).filter(e => e.mode === 'trigger');
  const last = runs.reduce((m, e) => Math.max(m, Date.parse(e.startedAt)), 0);
  const silentFor = last ? now - last : null;
  if (silentFor !== null && silentFor > expected * cfg.graceFactor) {
    findings.push({ kind: 'silent', workflow: w.name,
      what: `Schedule is active but the last automatic run was ${Math.round(silentFor / min)} min ago (expected every ${Math.round(expected / min)} min). No error was raised.`,
      next: `Deactivate and re-activate the workflow to re-register the trigger; check credentials used by the first node; check instance restarts.`, url: `${cfg.baseUrl}/workflow/${w.id}` });
  }
}

return [{ json: { count: findings.length, findings } }];
